import os
from datetime import datetime
from taf.ul.sc.perf.tc import tc


def get_tester_username():
    tester_username = os.environ['TESTER_USERNAME'] if 'TESTER_USERNAME' in os.environ else None
    return tester_username


def get_test_line_status():
    now = datetime.now()
    now_str = now.strftime("%Y-%m-%d %H:%M:%S")
    test_line_status = {
        "setup_name": tc.test_line_name,
        "test_case": tc.test_case_name,
        "setup_owner": tc.test_line_owner,
        "build": tc.bts_build,
        "release": tc.bts_release,
        "jenkins_job_link": "https://www.google.com/",
        "user_id": tc.tester_username,
        "time": now_str,
    }

    return test_line_status


def get_absolute_path(file_path):
    """

    :param file_path: absolute or relative path to the file
    :return: Absolute path to the file or None if file doesn't exists
    """

    if os.path.isfile(file_path):
        return os.path.abspath(file_path)
    else:
        dir_names = _get_all_dir_paths()
        for dir_name in dir_names:
            abs_file_path = os.path.abspath(os.path.join(dir_name, file_path))
            if os.path.isfile(abs_file_path):
                return abs_file_path


def _get_all_dir_paths():
    dir_names = set()
    if tc.run_params['environment'].get('test_case_dir'):
        dir_names.update(_get_test_case_dir())
    if tc.run_params['environment']['test_line_dir']:
        dir_names.add(tc.run_params['environment'].get('test_line_dir'))
    if tc.run_params['environment'].get('common_dir'):
        dir_names.add(tc.run_params['environment'].get('common_dir'))

    return dir_names


def _get_test_case_dir():
    if isinstance(tc.run_params['environment'].get('test_case_dir'), list):
        return tc.run_params['environment'].get('test_case_dir')
    return list(tc.run_params['environment'].get('test_case_dir'))
